using Alterverse.Characters;using Alterverse.Combat;using Alterverse.Match;using Alterverse.Visuals;using UnityEngine;
namespace Alterverse.UI
{
public sealed class TargetIndicatorHUD:MonoBehaviour
{
private SoftTargeting targeting;private Camera cachedCamera;private Texture2D pixel;private GUIStyle label;private float nextResolve,lastScale=-1;private void Start(){pixel=new Texture2D(1,1);pixel.SetPixel(0,0,Color.white);pixel.Apply();cachedCamera=Camera.main;ResolveTargeting();}private void Update(){if(targeting==null&&Time.unscaledTime>=nextResolve)ResolveTargeting();if(cachedCamera==null)cachedCamera=Camera.main;}
private void ResolveTargeting(){nextResolve=Time.unscaledTime+.5f;PlayerHeroAbilities player=FindAnyObjectByType<PlayerHeroAbilities>();if(player!=null)targeting=player.GetComponent<SoftTargeting>();}
private void OnGUI(){Health h=targeting!=null?targeting.Current:null;if(h==null||cachedCamera==null||pixel==null)return;Vector3 s=cachedCamera.WorldToScreenPoint(h.transform.position+Vector3.up*1.25f);float scale=Mathf.Clamp(Screen.height/900f,.72f,1.25f),margin=80*scale;if(s.z<=0||s.x<-margin||s.x>Screen.width+margin||s.y<-margin||s.y>Screen.height+margin)return;s.y=Screen.height-s.y;bool objective=h.GetComponent<DimensionPlanet>()!=null;float pulse=1f+Mathf.Sin(Time.unscaledTime*5f)*.08f,size=(objective?64:48)*scale*pulse;Color c=objective?StylizedArtDirection.WarmAccent:new Color(1,.25f,.28f,.95f);Color old=GUI.color;GUI.color=c;float t=(objective?4:3)*scale,arm=size*.27f;GUI.DrawTexture(new Rect(s.x-size*.5f,s.y-size*.5f,arm,t),pixel);GUI.DrawTexture(new Rect(s.x+size*.5f-arm,s.y-size*.5f,arm,t),pixel);GUI.DrawTexture(new Rect(s.x-size*.5f,s.y+size*.5f-t,arm,t),pixel);GUI.DrawTexture(new Rect(s.x+size*.5f-arm,s.y+size*.5f-t,arm,t),pixel);GUI.DrawTexture(new Rect(s.x-size*.5f,s.y-size*.5f,t,arm),pixel);GUI.DrawTexture(new Rect(s.x-size*.5f,s.y+size*.5f-arm,t,arm),pixel);GUI.DrawTexture(new Rect(s.x+size*.5f-t,s.y-size*.5f,t,arm),pixel);GUI.DrawTexture(new Rect(s.x+size*.5f-t,s.y+size*.5f-arm,t,arm),pixel);GUI.color=new Color(c.r,c.g,c.b,.45f);GUI.DrawTexture(new Rect(s.x-scale,s.y-size*.68f,2*scale,size*.18f),pixel);GUI.DrawTexture(new Rect(s.x-scale,s.y+size*.5f,2*scale,size*.18f),pixel);GUI.color=old;EnsureStyle(scale);GUI.Label(new Rect(s.x-70*scale,s.y-size*.5f-22*scale,140*scale,20*scale),objective?"DIMENSION OBJECTIVE":"SOFT TARGET",label);}
private void EnsureStyle(float scale){if(label!=null&&Mathf.Abs(lastScale-scale)<.01f)return;lastScale=scale;label=new GUIStyle(GUI.skin.label){fontSize=Mathf.Max(9,Mathf.RoundToInt(11*scale)),fontStyle=FontStyle.Bold,alignment=TextAnchor.MiddleCenter};}private void OnDestroy(){if(pixel!=null)Destroy(pixel);}
}
}
